import React from 'react';
import Slider from 'react-slick';
import { Box, Typography, Button } from '@mui/material';

const events = [
  { title: 'Etkinlik 1', description: 'Açıklama 1', imageUrl: 'https://via.placeholder.com/150' },
  { title: 'Etkinlik 2', description: 'Açıklama 2', imageUrl: 'https://via.placeholder.com/150' },
  { title: 'Etkinlik 3', description: 'Açıklama 3', imageUrl: 'https://via.placeholder.com/150' },
  { title: 'Etkinlik 4', description: 'Açıklama 4', imageUrl: 'https://via.placeholder.com/150' },
];

function MiniSlider() {
  const settings = {
    dots: false, // Alt kısımda noktalar olmayacak
    infinite: true, // Sonsuz kaydırma
    speed: 500, // Geçiş süresi
    slidesToShow: 3, // Aynı anda gösterilecek kart sayısı
    slidesToScroll: 1, // Her kaydırmada bir kart
    nextArrow: <div className="custom-arrow next-arrow">→</div>, // Özel sağ ok
    prevArrow: <div className="custom-arrow prev-arrow">←</div>, // Özel sol ok
    responsive: [
      {
        breakpoint: 1024, // Ekran genişliği 1024px ve daha küçük olduğunda
        settings: {
          slidesToShow: 2,
        },
      },
      {
        breakpoint: 600, // Ekran genişliği 600px ve daha küçük olduğunda
        settings: {
          slidesToShow: 1,
        },
      },
    ],
  };

  return (
    <Box sx={{ padding: '20px', backgroundColor: '#F5F9FF', position: 'relative' }}>
      <Typography variant="h6" sx={{ marginBottom: '20px', textAlign: 'center', fontWeight: 'bold' }}>
        Popüler Etkinlikler
      </Typography>
      <Slider {...settings}>
        {events.map((event, index) => (
          <Box key={index} sx={{ padding: '10px', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <Box
              sx={{
                width: '100%',
                height: '150px',
                backgroundImage: `url(${event.imageUrl})`,
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                borderRadius: '8px',
                marginBottom: '10px',
              }}
            />
            <Typography variant="h6" sx={{ fontWeight: '500', fontSize: '18px', color: '#1D1D1D', textAlign: 'center' }}>
              {event.title}
            </Typography>
            <Typography sx={{ fontSize: '14px', color: '#878787', textAlign: 'center', marginBottom: '10px' }}>
              {event.description}
            </Typography>
            <Button variant="contained" sx={{ backgroundColor: '#00C26D', color: '#FFFFFF' }}>
              Başvur
            </Button>
          </Box>
        ))}
      </Slider>

      {/* Custom CSS for the arrows */}
      <style jsx>{`
        .slick-prev, .slick-next {
          font-size: 24px;
          color: #1D1D1D;
          z-index: 1;
          position: absolute;
          top: 50%;
          transform: translateY(-50%);
          cursor: pointer;
        }

        .slick-prev {
          left: -30px;
        }

        .slick-next {
          right: -30px;
        }

        /* Ok işaretlerine tıklama anında bir geçiş efekti eklemek */
        .slick-prev:hover, .slick-next:hover {
          color: #00C26D; /* Renk değişimi */
          transition: color 0.3s ease;
        }
      `}</style>
    </Box>
  );
}

export default MiniSlider;
